import React, { useState, useEffect } from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import { Link } from 'react-router-dom';
import { FaCar, FaMapMarkerAlt, FaShieldAlt, FaUsers } from 'react-icons/fa';
import { useSelector } from 'react-redux';

const LandingPage = () => {
  const { isAuthenticated, userRole } = useSelector((state) => state.auth);

  useEffect(() => {
    if (isAuthenticated) {
      if (userRole === 'user') {
        window.location.href = '/dashboard';
      } else if (userRole === 'captain') {
        window.location.href = '/captain-dashboard';
      }
    }
  }, [isAuthenticated, userRole]);

  return (
    <div className="min-h-screen flex flex-col bg-gray-50">
      <Header />

      {/* Hero Section */}
      <section className="bg-gradient-to-r from-blue-600 to-blue-800 text-white py-16">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-center">
            <div>
              <h1 className="text-5xl font-bold mb-6">
                Your Ride, Your Way
              </h1>
              <p className="text-xl mb-8 text-blue-100">
                Book reliable rides instantly with Ride Zilla. Safe, secure, and affordable transportation at your fingertips.
              </p>
              <div className="flex gap-4">
                <Link
                  to="/signup"
                  className="bg-white text-blue-600 px-8 py-3 rounded-lg font-bold hover:bg-blue-50 transition"
                >
                  Get Started
                </Link>
                <Link
                  to="/login"
                  className="border-2 border-white text-white px-8 py-3 rounded-lg font-bold hover:bg-white hover:text-blue-600 transition"
                >
                  Login
                </Link>
              </div>
            </div>
            <div className="hidden md:block">
              <img
                src="https://via.placeholder.com/500x400?text=Ride+Booking"
                alt="Ride Booking"
                className="rounded-lg shadow-xl"
              />
            </div>
          </div>
        </div>
      </section>

      {/* Features Section */}
      <section className="py-16">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <h2 className="text-3xl font-bold text-center mb-12">Why Choose Ride Zilla?</h2>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
            {[
              {
                icon: <FaCar size={40} />,
                title: 'Wide Range of Vehicles',
                desc: 'Choose from bikes, autos, cars, and more',
              },
              {
                icon: <FaShieldAlt size={40} />,
                title: 'Safe & Secure',
                desc: 'Verified drivers and real-time tracking',
              },
              {
                icon: <FaMapMarkerAlt size={40} />,
                title: 'Best Route',
                desc: 'Optimized routes for faster rides',
              },
              {
                icon: <FaUsers size={40} />,
                title: 'Great Drivers',
                desc: 'Professional and courteous captains',
              },
            ].map((feature, index) => (
              <div
                key={index}
                className="bg-white p-6 rounded-lg shadow-md hover:shadow-lg transition text-center"
              >
                <div className="text-blue-600 mb-4 flex justify-center">
                  {feature.icon}
                </div>
                <h3 className="text-xl font-bold mb-2">{feature.title}</h3>
                <p className="text-gray-600">{feature.desc}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* CTA Section */}
      <section className="bg-blue-600 text-white py-12">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
          <h2 className="text-3xl font-bold mb-6">Ready to Ride?</h2>
          <p className="text-xl mb-8 text-blue-100">
            Join thousands of users and captains on Ride Zilla today!
          </p>
          <Link
            to="/signup"
            className="bg-white text-blue-600 px-8 py-3 rounded-lg font-bold hover:bg-blue-50 transition inline-block"
          >
            Sign Up Now
          </Link>
        </div>
      </section>

      <Footer />
    </div>
  );
};

export default LandingPage;
